-- mobile-app/supabase/rollbacks/0132_seed_spring_boot_tutorial_batch09_rollback.sql
-- ROLLBACK for mobile-app/supabase/migrations/0132_seed_spring_boot_tutorial_batch09.sql (twin admin-panel/supabase/migrations/104_seed_spring_boot_tutorial_batch09.sql).
-- Generated by scripts/build-spring-boot-seed.mjs. NOT a migration: this folder is outside
-- supabase/migrations, so the CLI never applies it. Run it by hand, once, in one transaction.
--
-- Removes only the 9 topic(s) of batch 09 with their content blocks, and every mock test
-- attached to those topics (the seeded ones and any an admin added later) with its MCQs; then any of
-- these now-empty sections this batch introduced: database.
-- Deleting a mock test also deletes students' attempts on it, and deleting a topic deletes
-- its bookmarks; the counts are printed before anything is removed. Nothing outside this
-- course is touched. Safe to run twice: the second run finds nothing and changes nothing.
-- ----------------------------------------------------------------------------
do $rollback$
declare
  v_grid uuid; v_topics uuid[]; v_tests text[]; v_attempts int; v_bookmarks int; v_n int;
begin
  select id into v_grid from (select id, show_on_website, show_on_mobile from public.learning_grids where lower(slug) = 'spring-boot-tutorial' and source_kind = 'seed' and source_ref = 'spring_boot_tutorial') g;
  if v_grid is null then
    raise notice 'rollback: Spring Boot Tutorial grid not found, nothing to do.';
    return;
  end if;
  select coalesce(array_agg(id), '{}') into v_topics from public.learning_topics where grid_id = v_grid and source_kind = 'spring_boot_tutorial' and source_ref in ($sb291$database/jdbc-vs-jpa-vs-hibernate$sb291$, $sb292$database/connecting-spring-boot-to-mysql$sb292$, $sb293$database/connecting-spring-boot-to-postgresql$sb293$, $sb294$database/h2-in-memory-database$sb294$, $sb295$database/jpa-entity$sb295$, $sb296$database/primary-key-generation-strategies$sb296$, $sb297$database/jparepository$sb297$, $sb298$database/derived-query-methods$sb298$, $sb299$database/query-with-jpql-and-native-sql$sb299$);
  select coalesce(array_agg(id), '{}') into v_tests from public.practice_tests
   where learning_topic_id = any (v_topics) or id in ('pt-sb-jdbc-vs-jpa-vs-hibernate', 'pt-sb-connecting-spring-boot-to-mysql', 'pt-sb-connecting-spring-boot-to-postgresql', 'pt-sb-h2-in-memory-database', 'pt-sb-jpa-entity', 'pt-sb-primary-key-generation-strategies', 'pt-sb-jparepository', 'pt-sb-derived-query-methods', 'pt-sb-query-with-jpql-and-native-sql');
  select count(*) into v_attempts from public.test_attempts where test_id = any (v_tests);
  select count(*) into v_bookmarks from public.learning_bookmarks where topic_id = any (v_topics);
  raise notice 'rollback: removing % topic(s), % mock test(s); this also deletes % test attempt(s) and % bookmark(s).',
    cardinality(v_topics), cardinality(v_tests), v_attempts, v_bookmarks;
  delete from public.practice_tests where id = any (v_tests);          -- cascades test_questions, test_attempts
  delete from public.learning_topics where id = any (v_topics);        -- cascades learning_contents, learning_bookmarks
  delete from public.learning_sections s where s.grid_id = v_grid
    and s.slug in ('database')
    and not exists (select 1 from public.learning_topics t where t.section_id = s.id);
  get diagnostics v_n = row_count;
  raise notice 'rollback: removed % empty section(s).', v_n;
end
$rollback$;

notify pgrst, 'reload schema';
